input.sparql:
SELECT ?zone ?zoneName WHERE {
  ?ahu a brick:AirHandlingUnit .
  ?ahu rdfs:label "AHU02" .
  ?ahu brick:hasPart ?zone ;
       brick:servicedBy ?ahu .
}

SELECT ?p ?o ?olbl ?otype WHERE {
  ?ahu ref:ifcName "AHU02" .
  ?ahu ?p ?o .
  OPTIONAL { ?o rdfs:label ?olbl }
  OPTIONAL { ?o a ?otype }
}

SELECT ?p ?o ?ot ?olbl WHERE {
  ?ahu a brick:AirHandlingUnit .
  ?ahu ?p ?o .
  OPTIONAL { ?o a ?ot }
  OPTIONAL { ?o rdfs:label ?olbl }
}

SELECT ?p ?o ?olbl WHERE {
  ?ahu ref:ifcName "AHU02" .
  ?ahu brick:hasPart ?o .
  OPTIONAL { ?o rdfs:label ?olbl }
}

SELECT ?s ?sType ?o ?oType WHERE {
  ?s ref:ifcName ?sName . FILTER(?sName="AHU02").
  ?s ?p ?o .
  OPTIONAL { ?o a ?oType }
}

SELECT ?s ?sType ?slbl WHERE {
  ?s <https://brickschema.org/schema/Brick/ref#hasExternalReference> [ref:ifcName "AHU02"] .
  OPTIONAL { ?s a ?sType }
  OPTIONAL { ?s rdfs:label ?slbl }
}

SELECT ?p ?o ?ot ?olbl WHERE {
  ?ahu a brick:AHU .
  ?ahu ref:hasExternalReference [ref:ifcName "AHU02"].
  ?ahu ?p ?o .
  OPTIONAL { ?o a ?ot }
  OPTIONAL { ?o rdfs:label ?olbl }
}

SELECT ?vav ?zone ?zlbl WHERE {
  ?ahu a brick:AHU .
  ?ahu ref:hasExternalReference [ref:ifcName "AHU02"].
  ?ahu brick:feeds ?vav .
  ?vav brick:feeds ?zone .
  OPTIONAL { ?zone rdfs:label ?zlbl }
}

SELECT ?zone ?zlbl ?pt ?tsid ?ptlbl WHERE {
  ?pt brick:isPointOf ?zone .
  ?zone rdfs:label ?zlbl .
  FILTER(?zlbl IN ("Core_mid","Perimeter_mid_ZN_1","Perimeter_mid_ZN_2","Perimeter_mid_ZN_3","Perimeter_mid_ZN_4"))
  ?pt ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?pt rdfs:label ?ptlbl }
}

SELECT ?zone ?zlbl ?pt ?ptType ?tsid WHERE {
  ?pt brick:isPointOf ?zone .
  ?zone rdfs:label ?zlbl .
  FILTER(?zlbl IN ("Core_mid","Perimeter_mid_ZN_1","Perimeter_mid_ZN_2","Perimeter_mid_ZN_3","Perimeter_mid_ZN_4"))
  OPTIONAL { ?pt ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?pt a ?ptType }
}

SELECT ?pt ?tsid ?extref WHERE {
  ?pt brick:isPointOf ?zone .
  ?zone rdfs:label "Core_mid" .
  ?pt a brick:Zone_Air_Temperature_Sensor .
  ?pt ref:hasExternalReference ?extref .
  OPTIONAL { ?extref ref:hasTimeseriesId ?tsid }
}

